using System.ComponentModel; using System.Runtime.CompilerServices; using System.Windows.Input;
namespace MaintenancePRO.ViewModels; public abstract class BaseViewModel : INotifyPropertyChanged { public event PropertyChangedEventHandler? PropertyChanged; protected void OnPropertyChanged([CallerMemberName] string? name=null)=>PropertyChanged?.Invoke(this,new PropertyChangedEventArgs(name)); protected bool Set<T>(ref T field,T value,[CallerMemberName]string? name=null){if(EqualityComparer<T>.Default.Equals(field,value))return false;field=value;OnPropertyChanged(name);return true;} public ICommand NavigateCommand(string route)=>new Command(async()=>{try{await Shell.Current.GoToAsync(route);}catch(Exception ex){await Shell.Current.DisplayAlert("Navigation", "Impossible d’ouvrir cet écran. Réessaie.","OK");System.Diagnostics.Debug.WriteLine($"Navigation error: {ex}");}}); }